// AxISA v2.0 step 4 (see sw/string_test.axasm and docs/ISA.md's STRING
// section): STRING results AND per-instruction cycle counts, plus the
// illegal N-bank case. GENERATED by tools/gen_string_test.py.
`timescale 1ns/1ps
`ifndef INSTR_HEX
`define INSTR_HEX "sw/string_test.hex"
`endif

module tb_string;
    reg clk, reset;
    integer errors;
    integer max_cycles;
    integer cycle_count;

    wire halted;
    wire [31:0] tohost_value;
    wire        bus_req, bus_mem_write, bus_mem_unsigned, bus_grant;
    wire [31:0] bus_addr, bus_write_data, bus_read_data;
    wire [1:0]  bus_mem_size;
    wire        uart_tx_valid;
    wire [7:0]  uart_tx_data;

    cpu_core #(.INSTR_MEM_WORDS(1024), .INSTR_INIT_FILE(`INSTR_HEX)) dut (
        .clk(clk), .reset(reset), .halted(halted), .tohost_value(tohost_value),
        .irq_in(1'b0),
        .bus_req(bus_req), .bus_addr(bus_addr), .bus_write_data(bus_write_data),
        .bus_mem_write(bus_mem_write), .bus_mem_size(bus_mem_size), .bus_mem_unsigned(bus_mem_unsigned),
        .bus_grant(1'b0), .bus_read_data(32'b0),
        .uart_tx_valid(uart_tx_valid), .uart_tx_data(uart_tx_data),
        .uart_rx_data_in(8'b0), .uart_rx_ready_in(1'b0), .uart_rx_ack()
    );

    always #5 clk = ~clk;

    integer lat [0:10];
    integer n_lat, cur;
    initial begin n_lat = 0; cur = 0; end
    always @(posedge clk) begin
        if (!reset && dut.is_string) cur = cur + 1;
        else if (cur != 0) begin
            if (n_lat < 11) lat[n_lat] = cur;
            n_lat = n_lat + 1;
            cur = 0;
        end
    end

    task check(input [31:0] got, input [31:0] expected, input [64*8-1:0] name);
        begin
            if (got !== expected) begin
                $display("FAIL: %0s got=%0d (0x%h) expected=%0d (0x%h)", name, got, got, expected, expected);
                errors = errors + 1;
            end else begin
                $display("PASS: %0s = %0d (0x%h)", name, got, got);
            end
        end
    endtask

    initial begin
        errors = 0;
        max_cycles = 1000;

        clk = 0;
        reset = 1;
        cycle_count = 0;
        @(posedge clk); @(posedge clk);
        reset = 0;

        while (!halted && cycle_count < max_cycles) begin
            @(posedge clk);
            cycle_count = cycle_count + 1;
        end

        if (!halted) begin
            $display("FAIL: core never halted within %0d cycles", max_cycles);
            errors = errors + 1;
        end else begin
            $display("Halted after %0d cycles. tohost=%0d", cycle_count, tohost_value);
            check(tohost_value, 32'd1, "tohost (n7 = traps taken)");
            check(dut.n_bank.regs[6], 32'd0, "n6 (trap cause, 0 = ILLEGAL)");
            check(dut.n_bank.regs[4], 32'd55, "n4 (sentinel: illegal STRING wrote nothing)");
            check(dut.dmem.mem[11'h100], 32'h00000000, "result: same place: no string");
            check(dut.dmem.mem[11'h101], 32'h00000001, "result: d=1");
            check(dut.dmem.mem[11'h102], 32'h00000005, "result: d=5, reversed order");
            check(dut.dmem.mem[11'h103], 32'h000003E8, "result: d=1000");
            check(dut.dmem.mem[11'h104], 32'h00007FFF, "result: d=0x7FFF, 15 bits");
            check(dut.dmem.mem[11'h105], 32'h0000FFFF, "result: d=0xFFFF, longest unbroken string");
            check(dut.dmem.mem[11'h106], 32'h00010000, "result: d=2^16: first break, 1 pair");
            check(dut.dmem.mem[11'h107], 32'h00030005, "result: 3 pairs + a 5-long segment");
            check(dut.dmem.mem[11'h108], 32'h000000FA, "result: negative position");
            check(dut.dmem.mem[11'h109], 32'hFFFFFFFF, "result: d=2^32-1, the widest");
            check(dut.dmem.mem[11'h10A], 32'h00000000, "result: end-marker slot stays 0");
            check(n_lat, 11, "number of STRING instructions timed");
            check(lat[0], 1, "cycles: same place: no string");
            check(lat[1], 2, "cycles: d=1");
            check(lat[2], 4, "cycles: d=5, reversed order");
            check(lat[3], 11, "cycles: d=1000");
            check(lat[4], 16, "cycles: d=0x7FFF, 15 bits");
            check(lat[5], 17, "cycles: d=0xFFFF, longest unbroken string");
            check(lat[6], 17, "cycles: d=2^16: first break, 1 pair");
            check(lat[7], 17, "cycles: 3 pairs + a 5-long segment");
            check(lat[8], 9, "cycles: negative position");
            check(lat[9], 17, "cycles: d=2^32-1, the widest");
            check(lat[10], 1, "cycles: illegal STRING on N traps at once");
        end

        if (errors == 0) $display("ALL AXISA STRING TESTS PASSED");
        else $display("%0d AXISA STRING TEST(S) FAILED", errors);
        $finish;
    end
endmodule
